/* Local-only interface styles. No remote fonts, images, or CDN assets. */

/*
 * Warm-dark tokens reconstructed from the reference screenshot as starting
 * values (UX-01). They are approximate calibration targets, not exact
 * Superhuman values; geometry is calibrated on real displays later.
 */
:root {
  color-scheme: dark;
  font-family: var(--font-ui);
  /*
   * Type scale (DESIGN.md "Typography"): one local system sans, a fixed rem
   * scale, two weights. Hierarchy comes from weight (600 vs 400) and tone
   * (Paper White vs Ash), not from extra sizes.
   */
  --font-ui: system-ui, -apple-system, sans-serif;
  --font-mono: ui-monospace, monospace;
  /* 16px: split tabs, context title, contact name, drawer and reader headings. */
  --type-headline: 1rem;
  /* 12px: everything else in the app shell (rows, rail, panes, drawers, reader chrome). */
  --type-body: 0.75rem;
  /* 11px: split-tab counts only. */
  --type-count: 0.6875rem;
  /* Plain-text message bodies in the reader (monospace runs visually larger). */
  --type-mono: 0.85rem;
  /* 15px: prose message bodies in the reader (proportional face). */
  --type-reading: 0.9375rem;
  --weight-regular: 400;
  --weight-strong: 600;
  --leading-headline: 1.25;
  --leading-ui: 1.35;
  --leading-mono: 1.45;
  --leading-reading: 1.6;
  --surface: #292826;
  --surface-contact: #1f1e1c;
  --surface-raised: #33312e;
  --focus-fill: #474644;
  --focus-accent: #bba5ed;
  /* DESIGN.md Paper White: 14.7:1 on Warm Charcoal, 9.4:1 on Focus Stone. */
  --text-primary: #ffffff;
  /* DESIGN.md Ash: >=4.5:1 on Focus Stone (4.99:1; the old #a8a29a was 3.73:1). */
  --text-secondary: #c0bcb6;
  /* DESIGN.md Smoke (inactive split tabs, on Warm Charcoal only: 5.4:1) and
     Graphite (resting glyphs). */
  --text-tertiary: #a09c9a;
  --icon-muted: #8e8a87;
  /* DESIGN.md split-header height: content top to the first row. */
  --split-header-height: 78px;
  --unread-marker: #ce9ece;
  /* DESIGN.md Seam: the 1px vertical separators between rail, list and
     contact pane (and the drawer's leading edge), utility-chip and input
     borders. Never between rows. */
  --divider: #474543;
  /* Quieter structural rule inside a pane (reader message stack, drawer list
     rows): the pre-polish Seam value, kept so the reader and drawers do not
     change tone until a reader reference is captured. */
  --rule: #3b3936;
  /* Overlay lift (DESIGN.md "Elevation"): palette/navigator and the modal
     attachment chooser, over a dimmed shell. */
  --overlay-backdrop: rgba(0, 0, 0, 0.53);
  --overlay-lift: 0 16px 64px rgba(0, 0, 0, 0.53);
  /* DESIGN.md Inkwell (rail destination pill) and Rail Pebble (28px circle,
     active destination). */
  --rail-well: #141413;
  --rail-button: #383735;
  /* Pane geometry shared by the rail and the contact pane so their lines
     follow the list column: the split-tab line is centered 42px down (6px
     header pad + half of its 72px row), the first list line is the 36px row
     right below the 78px header. */
  --rail-width: 40px;
.row-group {
  display: flex;
  align-items: flex-end;
  min-height: 48px;
  padding: 0 0 10px 50px;
  font-size: var(--type-body);
  line-height: var(--leading-ui);
  color: var(--text-secondary);
}

/* A visually hidden leading Today caption takes no box at all. */
.row-group.visually-hidden {
  min-height: 0;
  padding: 0;
}

/* Reader: a bounded flex surface with its own content scroller; the toolbar
   (and its Back affordance) stays persistent while the message stack scrolls. */
.reader-pane,
.reader {
  min-height: 0;
  min-width: 0;
}

.reader-pane {
  display: flex;
  flex-direction: column;
  padding: 0.5rem 0.75rem;
}

.reader {
  flex: 1;
  display: flex;
  flex-direction: column;
}

.reader:focus {
  outline: none;
}

/* Quiet icon actions teleported into the app header: the hosts take no box of
   their own so the glyphs sit on the header's 32px pitch. Standalone (no
   host) they flow inline. */
.reader-back-host,
.reader-actions-host {
  display: contents;
}

.reader-actions {
  display: flex;
  align-items: center;
  flex: 0 0 auto;
}

/* Back arrow leads the context title; its glyph sits on the 50px inset. */
.header-tabs > .reader-back-host > .reader-back {
  align-self: center;
  margin-left: -8px;
  margin-right: -10px;
}

.header-tabs:has(> .reader-back-host > .reader-back) {
  align-items: center;
}

/* Honest-state text controls under the subject: one quiet line, only when present. */
.reader-meta-row {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 12px;
  color: var(--text-secondary);
}

.reader-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}

/* Headline at the strong weight: the subject leads the reader without a third size. */
.reader-subject {
  font-size: var(--type-headline);
  font-weight: var(--weight-strong);
  line-height: var(--leading-headline);
  overflow-wrap: anywhere;
}

/* Loading identity: the list row's sender and date under the subject, then one
   quiet line. No motion; same type scale as the loaded reader. */
.reader-loading-identity {
  display: flex;
  gap: 12px;
  margin: 0.2rem 0;
  color: var(--text-secondary);
}

.reader-loading-quiet {
  color: var(--text-secondary);
}

/* Static placeholder bars in the Rule colour: the subject line, then rows at the
   collapsed message height (2em). No shimmer: nothing moves while loading. */
.reader-skeleton {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-top: 0.5rem;
}

.reader-skeleton-subject,
.reader-skeleton-row {
  display: block;
  background: var(--rule);
  border-radius: 4px;
  opacity: 0.6;
}

.reader-skeleton-subject {
  height: var(--type-headline);
  width: 40%;
}

.reader-skeleton-row {
  height: 1.4em;
  width: 100%;
}

.reader-context-note {
  max-width: 80ch;
  margin: 0.2rem 0;
  color: var(--text-secondary);
  font-size: var(--type-body);
}

/* Partial, unknown and unconfirmed star state read as Amber Notice. */
.reader-context-note[data-attention] {
  color: var(--warning);
}

.reader-pending {
  margin: 0.2rem 0;
  color: var(--warning);
  font-size: var(--type-body);
}

/* The standing read-state guarantee: one muted status line in the meta row.
   The sentence itself is its title and visually hidden text. */
.reader-status {
  display: inline-flex;
  align-items: baseline;
  gap: 0.35em;
}

.reader-status-word::after {
  content: ' ·';
}

.messages {
  list-style: none;
  padding: 0;
  margin: 0;
}

.message {
  position: relative;
  border-top: 1px solid var(--rule);
  padding: 0.4rem 0.4rem 0.6rem;
  margin-bottom: 0.5rem;
}

/*
 * Current-message treatment: an accent-purple bar (color) plus a non-color
 * indication (a flat raised fill and a primary-color sender) so the focused
 * message never relies on color alone.
 */
.message.message-active {
  background: var(--surface-raised);
  box-shadow: inset 3px 0 0 var(--focus-accent);
}

/* The active bar is the focus indicator for the message toggle: no second ring.
   The fill, bold sender and bar remain; other controls keep the global ring. */
.message.message-active .message-toggle:focus-visible {
  outline: none;
}

.message.message-active .message-from {
  color: var(--text-primary);
  font-weight: var(--weight-strong);
}

.message-header {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

/* Quiet per-message reply glyph (latest, active message only). */
.message-reply {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 0;
  color: var(--icon-muted);
  background: transparent;
}

.message-reply:hover:not(:disabled),
.message-reply:focus-visible {
  color: var(--text-primary);
  background: transparent;
}

.message-reply-glyph {
  width: 1rem;
  height: 1rem;
}

/*
 * One line per message: sender, then (collapsed) a clipped body snippet or
 * (expanded) the recipients, then the compact date right-aligned. The full
 * date stays in the title, the screen-reader text and the Details disclosure.
 */
.message-toggle {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex: 1;
  min-width: 0;
  min-height: 2em;
  text-align: left;
  font-size: var(--type-body);
  color: var(--text-secondary);
  background: transparent;
  border: 0;
  padding: 0.1rem 0.2rem;
}

.message-from,
.message-to {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Collapsed senders share one 132px column so the snippets line up. */
.message-toggle[aria-expanded='false'] .message-from {
  flex: 0 0 11em;
}

.message-toggle[aria-expanded='false'] .message-to {
  display: none;
}

.message-snippet {
  flex: 1 1 0;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.message-time {
  flex: none;
  margin-left: auto;
  text-align: right;
  text-transform: uppercase;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

/*
 * Prose reads in the proportional face at the reading size. 65ch (width of "0")
 * is about 90 average proportional characters per line, short enough to follow.
 * Bodies that rely on column alignment (quotes, indented blocks, tables) keep
 * the raw monospace.
 */
.message-body {
  white-space: pre-wrap;
  font-family: var(--font-ui);
  font-size: var(--type-reading);
  line-height: var(--leading-reading);
  max-width: 65ch;
  color: var(--text-primary);
  overflow-wrap: anywhere;
  margin: 0.4rem 0;
}

.message-body.message-body-mono {
  font-family: var(--font-mono);
  font-size: var(--type-mono);
  line-height: var(--leading-mono);
  /* Hard-wrapped plain text is 72-78 columns; do not soft-wrap it a second time. */
  max-width: 88ch;
}

/* Signature and trailing quote: the same reading face as the prose, in Ash. The
   text is literal (pre-wrap, ">" kept); only the colour steps back. */
.message-trail {
  white-space: pre-wrap;
  font-family: var(--font-ui);
  font-size: var(--type-reading);
  line-height: var(--leading-reading);
  max-width: 65ch;
  color: var(--text-secondary);
  overflow-wrap: anywhere;
  margin: 0.4rem 0;
}

.message-quote-toggle {
  margin: 0 0 0.2rem;
  color: var(--text-secondary);
}

.message-quote-toggle:hover:not(:disabled) {
  background: var(--focus-fill);
  color: var(--text-primary);
}

/* Per-message participant details disclosure (native details/summary). Only
   rendered visible inside an expanded message: the summary is a quiet line
   under the header (in flow, so it can never collide with the date or the reply
   glyph); the fields open below it. */
.message-details {
  font-size: var(--type-body);
}

.message-details summary {
  width: max-content;
  margin-left: 0.2rem;
  cursor: pointer;
  /* Ash: Graphite text is 3.79:1 on the active message's raised fill. */
  color: var(--text-secondary);
  list-style: none;
}

.message-details summary::-webkit-details-marker {
  display: none;
}

.message-details summary::before {
  content: '▸ ';
}

.message-details[open] summary::before {
  content: '▾ ';
}

.message-details summary:hover {
  color: var(--text-primary);
}

.message-details summary:focus-visible {
  outline: 2px solid var(--focus-accent);
  outline-offset: 1px;
}

.message-fields {
  display: grid;
  gap: 0.2rem;
  padding: 0.3rem 0;
}

.message-field {
  display: flex;
  gap: 0.4rem;
  min-width: 0;
}

.message-field-label {
  flex: 0 0 auto;
  color: var(--text-secondary);
}

.message-field-recipients {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

/* Participant context controls: hover/focus context, never navigation. */
.participant {
  overflow-wrap: anywhere;
  text-decoration: underline dotted;
  cursor: default;
}

.participant:hover,
.participant:focus-visible {
  color: var(--text-primary);
}

/* Contact copy glyphs: revealed per line on hover/focus, always keyboard
   reachable (opacity only, never display/visibility). */
.contact-copy {
  flex: 0 0 auto;
  display: inline-grid;
  place-items: center;
  width: 24px;
  height: 24px;
  padding: 0;
  background: transparent;
  border: 0;
  border-radius: 4px;
  color: var(--icon-muted);
  opacity: 0;
  cursor: pointer;
}

.contact-line:hover .contact-copy,
.contact-line:focus-within .contact-copy,
.contact-copy:focus-visible {
  opacity: 1;
}

.contact-copy:hover,
.contact-copy:focus-visible {
  color: var(--text-primary);
}

.contact-copy-status {
  margin: 12px 0 0;
  font-size: var(--type-body);
  color: var(--text-secondary);
}

/* Activity (inside its utility disclosure). */
/* In-panel headings are Title labels under the drawer's Headline. */
.activity-title {
  font-size: var(--type-body);
  font-weight: var(--weight-strong);
  margin: 0 0 0.5rem;
}

.activity-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.activity-row {
  border-bottom: 1px solid var(--rule);
  padding: 0.4rem 0;
  font-size: var(--type-body);
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.status-queued,
.status-applying {
  font-style: italic;
}

.status-outcome_unknown,
.activity-warning,
.activity-error,
.account-action-error {
  color: var(--warning);
}

.activity-warning,
.activity-error {
  margin: 0;
}

.status-failed {
  color: var(--danger);
  font-weight: var(--weight-strong);
}

.activity-buttons {
  display: flex;
  gap: 0.4rem;
}

/* Local-only plain-text drafts; fields remain ordinary text controls. */
.drafts-pane {
  display: grid;
  grid-template-columns: minmax(190px, 0.7fr) minmax(0, 2fr);
  gap: 0.8rem;
  min-height: 0;
}

.draft-list,
.composer {
  min-width: 0;
}

.draft-list-heading,
.composer-heading,
.composer-actions,
.conflict-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.draft-list-heading h2,
.composer-heading h2 {
  font-size: var(--type-body);
  font-weight: var(--weight-strong);
  margin: 0.25rem 0;
  overflow-wrap: anywhere;
}

/* Informational note: secondary text, not a warning. Warnings stay on
   status/error lines (draft-status, reply-source). */
.draft-local-note {
  margin: 0.3rem 0;
  font-size: var(--type-body);
  color: var(--text-secondary);
}

.draft-status {
  margin: 0.3rem 0;
  font-size: var(--type-body);
  color: var(--warning);
}

/* Settled and idle: Ash. Saving, unconfirmed, conflict and non-durable states
   keep Amber Notice because they are not settled facts. */
.draft-status.draft-status-calm {
  color: var(--text-secondary);
}

/* The status line plus its small info toggle. The toggle is Ash (Graphite is
   under the 4.5:1 floor on the composer's Lifted Charcoal) and rises to Paper
   White on hover and focus. */
.composer-status-group {
  display: inline-flex;
  align-items: baseline;
  gap: 0.25rem;
  flex: 0 1 auto;
  min-width: 0;
}

.composer-caveat-toggle {
  flex: none;
  align-self: center;
  display: inline-flex;
  padding: 2px;
  color: var(--text-secondary);
}

.composer-caveat-toggle:hover:not(:disabled),
.composer-caveat-toggle[aria-expanded="true"] {
  color: var(--text-primary);
}

.composer-caveat {
  margin: 0.1rem 0 0.2rem;
  color: var(--text-secondary);
  font-size: var(--type-body);
  line-height: var(--leading-ui);
}

/* Heading line: the title on the left, the one status line on the right. */
.composer-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.25rem 0.75rem;
  flex-wrap: wrap;
}

.composer-top-main {
  flex: 1 1 auto;
  min-width: 0;
}

.composer-top .draft-status {
  flex: 0 1 auto;
  margin: 0.25rem 0;
  overflow-wrap: anywhere;
}

/* Shared composer body (DraftEditorCore) inside any surface. */
.composer-body {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  min-width: 0;
}

/* "Draft" state flag: plain strong text, never uppercase/tracked and never a
   second accent — the reader's active-message bar already owns focus-accent. */
.draft-flag {
  color: var(--text-primary);
  font-weight: var(--weight-strong);
}

/* Composer footer, shared by the inline compose card, the docked reply
   composer and the drafts-drawer editor: actions right-aligned above a rule. */
.composer-footer {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-top: 0.4rem;
  padding-top: 0.5rem;
  border-top: 1px solid var(--rule);
}

/* Primary: Focus Stone fill, Title weight, 4px radius, 24px tall. Hover adds an
   Ash inset ring (the fill alone is invisible against the raised surface). */
.composer-footer .composer-primary {
  background: var(--focus-fill);
  color: var(--text-primary);
  border: 0;
  border-radius: 4px;
  padding: 4px 8px;
  font-weight: var(--weight-strong);
}

.composer-footer .composer-primary:hover:not(:disabled) {
  background: var(--focus-fill);
  box-shadow: inset 0 0 0 1px var(--text-secondary);
}

.composer-footer .composer-primary:active:not(:disabled) {
  background: var(--rail-button);
  box-shadow: inset 0 0 0 1px var(--text-secondary);
}

.composer-kbd {
  margin-left: -0.25rem;
  color: var(--text-secondary);
  font: inherit;
}

/* Secondary actions: quiet Ash ghosts. */
.composer-footer .composer-quiet {
  background: transparent;
  color: var(--text-secondary);
  border: 0;
  padding: 4px 8px;
}

.composer-footer .composer-quiet:hover:not(:disabled) {
  background: var(--focus-fill);
  color: var(--text-primary);
}

.composer-footer .composer-discard {
  margin-left: auto;
}

/* Inline confirm dialog (discard / reload) on any composer surface. */
.discard-confirm {
  border: 1px solid var(--rule);
  border-radius: 6px;
  padding: 0.4rem 0.6rem;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
