.field-row .field-input {
  background: transparent;
  border: 1px solid transparent;
  border-bottom-color: var(--divider);
  border-radius: 4px;
}

.field-row .field-input:hover:not(:disabled) {
  border-color: var(--divider);
}

.field-row .field-input:focus-visible {
  border-color: var(--focus-accent);
  outline: 1px solid var(--focus-accent);
  outline-offset: -2px;
}

/* The collapsed reply recipient: a real button that opens the To input. */
.field-row .field-summary {
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-primary);
}

/* The real address sits beside the display name in Ash, so a name can never hide it. */
.field-summary-address {
  color: var(--text-secondary);
}

.field-row .field-summary:hover:not(:disabled) {
  background: var(--focus-fill);
}

.field-toggle {
  flex: none;
  color: var(--text-secondary);
}

.field-toggle:hover:not(:disabled) {
  color: var(--text-primary);
}

.field-body {
  display: flex;
  flex-direction: column;
  min-width: 0;
  margin-top: 0.25rem;
}

.field-textarea {
  width: 100%;
  min-width: 0;
